pub fn tactician_power_points_total(level: u8, int_mod: i16) -> Option<i16> {
    if level < 1 {
        return None;
    }
    let ladder = crate::rules_core::rules_catalog::rows::<
        crate::rules_core::rules_data_package::PowerPointsBaseRow,
    >("ultimate_psionics/tactician_features/tactician_power_points_total");
    let base = ladder
        .iter()
        .find(|row| row.level == level.min(20))?
        .base_power_points;
    Some(base + (int_mod * i16::from(level)) / 2)
}
